function planSection() { return `<section class="plan-section"><div class="section-heading"><div><p class="eyebrow">Manual bank transfer</p><h2>Choose your access</h2></div><span class="muted">Exact amounts only</span></div><div class="plans">${plans.map(plan => `<article class="plan-card ${plan.premium ? "premium-plan" : ""}"><span class="plan-number">0${plans.indexOf(plan) + 1}</span><h3>${plan.name}</h3><strong>${money(plan.price)}</strong><p>${plan.duration} of CBT access</p><button class="button" data-plan="${plan.id}">Choose plan</button></article>`).join("")}</div></section>`; }
function paymentRow(item) { return `<div class="history-row"><div><strong>${escape(item.planName)}</strong><span>${new Date(item.createdAt).toLocaleDateString()}</span></div><span class="badge ${item.status}">${item.subscriptionStatus === "approved_pending_activation" ? "Approved - awaiting activation" : item.status}</span></div>`; }
async function activate(event) { event.currentTarget.disabled = true; try { await api("subscriptions", { action: "activate", paymentId: event.currentTarget.dataset.activate }); notify("Subscription activated."); await dashboard(); } catch (error) { notify(error.message, true); event.currentTarget.disabled = false; } }
async function startDemo(event) { event.currentTarget.disabled = true; event.currentTarget.textContent = "Starting demo..."; try { await api("subscriptions", { action: "start-demo" }); notify("Demo mode is active for 20 minutes."); await dashboard(); } catch (error) { notify(error.message, true); event.currentTarget.disabled = false; event.currentTarget.textContent = "Try demo mode"; } }
function faqView() { app.innerHTML = `<section class="narrow"><div class="page-heading"><div><p class="eyebrow">Need a hand?</p><h1>Frequently asked questions.</h1><p class="muted">Quick answers about access, payments, and turning your notes into practice.</p></div></div><div class="faq-list"><details><summary>What is the DANS CBT app?</summary><p>DANS CBT is a learning platform where you can subscribe, upload your course PDFs, turn them into practice questions, and test your knowledge.</p></details><details><summary>How do I subscribe to DANS CBT?</summary><p>Choose a plan, make a manual payment using the exact amount shown, then submit genuine payment proof. Payments are verified before access is approved.</p></details><details><summary>What if I pay less than the expected amount?</summary><p>No. Make sure you pay the exact amount for your selected plan. Payments are not refunded for an incorrect amount.</p></details><details><summary>I made the right payment but uploaded the wrong receipt. What should I do?</summary><p>Do not submit another request. Tap the floating WhatsApp button to contact customer support, keep your proof of payment, and explain the problem. You will be approved once the payment is confirmed.</p></details><details><summary>How does demo mode work?</summary><p>New accounts can try the full CBT experience once for 20 minutes. Demo access includes PDF upload and practice, and a subscription is required after the timer ends.</p></details></div></section>`; }
function startCountdown() { clearInterval(examTimer); const element = document.querySelector("[data-end]"); if (!element || !element.dataset.end) return; const tick = () => { const remaining = Math.max(0, new Date(element.dataset.end).getTime() - Date.now()); const seconds = Math.floor(remaining / 1000); element.firstChild.textContent = [Math.floor(seconds / 3600), Math.floor(seconds % 3600 / 60), seconds % 60].map(value => String(value).padStart(2, "0")).join(":"); if (!remaining) { clearInterval(examTimer); notify("Your subscription has expired.", true); } }; tick(); examTimer = setInterval(tick, 1000); }
function paymentView(planId) { const plan = plans.find(item => item.id === planId); app.innerHTML = `<section class="narrow"><a href="#dashboard" class="back">← Back to dashboard</a><div class="page-heading"><div><p class="eyebrow">Payment request</p><h1>${plan.name}</h1><p class="muted">Transfer the exact amount, then submit genuine proof for review.</p></div><strong class="amount">${money(plan.price)}</strong></div><div class="payment-grid"><article class="panel instructions"><p class="eyebrow">Transfer to</p><h2>PalmPay</h2>${["Bank|PalmPay", "Account name|Jane Godwin Ekaidem", "Account number|7049267637", "Required amount|" + money(plan.price)].map(item => { const [label, value] = item.split("|"); return `<div class="copy-row"><span>${label}<strong>${value}</strong></span><button class="icon-button" data-copy="${value}" title="Copy ${label}">Copy</button></div>`; }).join("")}<div class="warning"><strong>Before you submit</strong><p>Please make sure you have transferred the exact amount for the plan you selected. Fake, edited, or fraudulent payment receipts will be completely rejected and will not qualify for a refund. Only submit genuine payment proof belonging to the transfer you made.</p></div><button class="button" id="submit-proof">I have transferred the exact amount</button></article></div></section>`; document.querySelectorAll("[data-copy]").forEach(button => button.addEventListener("click", async () => { await navigator.clipboard.writeText(button.dataset.copy); notify("Copied to clipboard."); })); document.querySelector("#submit-proof").addEventListener("click", () => receiptModal(plan)); }
function receiptModal(plan) { const modal = document.createElement("div"); modal.className = "modal-wrap"; modal.innerHTML = `<div class="modal panel"><button class="modal-close">×</button><p class="eyebrow">Honesty check</p><h2>Submit payment proof</h2><p class="muted">Your receipt will be reviewed by an administrator. Make sure it is genuine and readable.</p><form id="receipt-form"><input type="file" name="receipt" accept=".jpg,.jpeg,.png,.pdf,application/pdf,image/jpeg,image/png" required><label class="check"><input type="checkbox" name="honest" required> I agree that this is a genuine and honest transfer.</label><button class="button" disabled>Submit proof</button></form></div>`; document.body.append(modal); modal.querySelector(".modal-close").onclick = () => modal.remove(); const form = modal.querySelector("form"); const button = form.querySelector("button"); const file = form.querySelector("input[type=file]"); const check = form.querySelector("input[type=checkbox]"); const update = () => button.disabled = !(file.files[0] && check.checked); file.onchange = update; check.onchange = update; form.onsubmit = async event => { event.preventDefault(); button.disabled = true; button.textContent = "Uploading..."; try { const selected = file.files[0]; if (selected.size > 8 * 1024 * 1024) throw new Error("Receipt must be smaller than 8 MB."); const buffer = await selected.arrayBuffer(); const bytes = new Uint8Array(buffer); const base64 = btoa(bytes.reduce((data, byte) => data + String.fromCharCode(byte), "")); const created = await api("payments", { action: "create", planId: plan.id }); await api("payments", { action: "submit-proof", paymentId: created.id, honest: true, receiptData: `data:${selected.type || "application/pdf"};base64,${base64}` }); modal.remove(); notify("Payment proof submitted for review."); await dashboard(); } catch (error) { notify(error.message, true); button.disabled = false; button.textContent = "Submit proof"; } }; }
async function uploadView() { app.innerHTML = `<section class="narrow"><a href="#dashboard" class="back">← Back to dashboard</a><div class="page-heading"><div><p class="eyebrow">Question bank builder</p><h1>Bring your study material.</h1><p class="muted">Text and scanned PDFs are supported where readable content can be recovered.</p></div></div><form class="dropzone panel" id="pdf-form"><span class="upload-symbol">↑</span><h2>Upload one PDF</h2><p>The file must have a valid PDF signature.</p><input type="file" name="pdf" accept="application/pdf,.pdf" required><button class="button" type="submit">Process PDF</button><div id="process-status" class="muted"></div></form></section>`; document.querySelector("#pdf-form").onsubmit = async event => { event.preventDefault(); const form = event.currentTarget; const file = form.pdf.files[0]; if (!file || file.type !== "application/pdf") return notify("Choose a PDF file.", true); const status = document.querySelector("#process-status"); const button = form.querySelector("button"); button.disabled = true; try { status.textContent = "Preparing secure upload..."; const upload = await api("documents", { action: "upload-signature" }); const formData = new FormData(); formData.append("file", file); formData.append("api_key", upload.apiKey); formData.append("timestamp", upload.timestamp); formData.append("signature", upload.signature); formData.append("folder", upload.folder); formData.append("public_id", upload.publicId); formData.append("type", upload.type); status.textContent = "Uploading PDF..."; const cloudinaryResponse = await fetch(upload.uploadUrl, { method: "POST", body: formData }); const cloudinaryData = await cloudinaryResponse.json(); if (!cloudinaryResponse.ok || !cloudinaryData.public_id) throw new Error(cloudinaryData.error?.message || "Cloud upload failed."); status.textContent = "Reading PDF..."; const result = await api("documents", { action: "process", fileName: file.name, cloudinaryPublicId: cloudinaryData.public_id, cloudinaryVersion: cloudinaryData.version }); status.textContent = `Question bank ready. ${result.questionCount} questions created.`; notify("Question bank ready."); location.hash = "practice"; } catch (error) { status.textContent = error.message; notify(error.message, true); button.disabled = false; } }; }
async function practiceView() { app.innerHTML = `<section class="narrow"><div class="page-heading"><div><p class="eyebrow">CBT simulator</p><h1>Choose a question bank.</h1><p class="muted">Select the PDF you want to use for this test.</p></div></div><div id="practice-resume"></div><div class="panel"><div id="bank-list"><p class="empty">Loading your PDFs...</p></div></div></section>`; try { const current = await api("exams", { action: "current" }); if (current.attempt) { document.querySelector("#practice-resume").innerHTML = `<div class="resume-banner"><div><span class="status-label">EXAM IN PROGRESS</span><h2>Continue where you stopped.</h2><p>Your answers are saved and the clock is still running.</p></div><button type="button" class="button" id="practice-resume-button">Resume exam</button></div>`; document.querySelector("#practice-resume-button").onclick = event => { event.currentTarget.disabled = true; exam = current.attempt; renderExam(current.attempt.remainingSeconds); }; } const result = await api("documents", { action: "list" }); const banks = result.banks || []; const list = document.querySelector("#bank-list"); list.innerHTML = banks.length ? banks.map(bank => `<article class="history-row"><div><strong>${escape(bank.title || "Study PDF")}</strong><span>${bank.questionCount || 0} questions</span></div><button type="button" class="button small" data-start-bank="${bank.id}">Take test</button></article>`).join("") : '<p class="empty">Upload a PDF before starting practice.</p>'; document.querySelectorAll("[data-start-bank]").forEach(button => button.onclick = async () => { button.disabled = true; await startExam(button.dataset.startBank); button.disabled = false; }); } catch (error) { notify(error.message, true); } }
async function adminView() { app.innerHTML = `<section class="narrow"><div class="page-heading"><div><p class="eyebrow">Verified administration</p><h1>Payment review.</h1><p class="muted">Review receipts and decide whether access can be activated.</p></div></div><div id="admin-list" class="history"><p class="empty">Loading payment requests...</p></div></section>`; try { const result = await api("payments", { action: "admin-list" }); document.querySelector("#admin-list").innerHTML = result.payments.map(item => `<article class="history-row"><div><strong>${escape(item.userName)} · ${escape(item.planName)}</strong><span>${escape(item.userEmail)} · ${item.status}</span></div><div>${item.receiptUrl ? `<a class="button small ghost" href="${escape(item.receiptUrl)}" target="_blank" rel="noreferrer">View receipt</a>` : "<span class='muted'>No receipt</span>"}${item.status === "pending" ? `<button class="button small" data-approve="${item.id}">Approve</button><button class="button small danger" data-reject="${item.id}">Reject</button>` : ""}</div></article>`).join("") || '<p class="empty">No payment requests.</p>'; document.querySelectorAll("[data-approve]").forEach(button => button.onclick = async () => { button.disabled = true; try { await api("payments", { action: "review", paymentId: button.dataset.approve, decision: "approve" }); notify("Payment approved."); adminView(); } catch (error) { notify(error.message, true); button.disabled = false; } }); document.querySelectorAll("[data-reject]").forEach(button => button.onclick = async () => { const reason = prompt("Reason for rejection"); if (!reason?.trim()) return; button.disabled = true; try { await api("payments", { action: "review", paymentId: button.dataset.reject, decision: "reject", reason }); notify("Payment rejected."); adminView(); } catch (error) { notify(error.message, true); button.disabled = false; } }); } catch (error) { document.querySelector("#admin-list").innerHTML = `<p class="empty">${escape(error.message)}</p>`; } }
async function analyticsView() { app.innerHTML = `<section class="analytics-page"><div class="page-heading"><div><p class="eyebrow">Verified administration</p><h1>Analytics.</h1><p class="muted">A live view of users, exams, payments, and learning performance.</p></div><a class="button ghost" href="#admin">Receipt review</a></div><div id="analytics-content" class="analytics-loading"><span class="loader"></span><p>Loading analytics...</p></div></section>`; try { const result = await api("analytics", null, "GET"); const data = result.analytics; const maxActivity = Math.max(1, ...data.activity.flatMap(item => [item.users, item.exams])); const bars = data.activity.map(item => `<div class="activity-day"><div class="activity-bars"><span class="activity-users" style="height:${Math.max(6, item.users / maxActivity * 100)}%" title="${item.users} new users"></span><span class="activity-exams" style="height:${Math.max(6, item.exams / maxActivity * 100)}%" title="${item.exams} exams"></span></div><small>${escape(item.label)}</small></div>`).join(""); const grades = Object.entries(data.grades).map(([grade, count]) => `<div class="grade-bar"><span><b>Grade ${grade}</b><small>${count} exams</small></span><i style="width:${data.totalExams ? count / data.totalExams * 100 : 0}%"></i></div>`).join(""); document.querySelector("#analytics-content").innerHTML = `<div class="analytics-grid"><article class="analytics-card accent"><span>New users today</span><strong>${data.todayUsers}</strong><small>${data.totalUsers} total users</small></article><article class="analytics-card"><span>Exams taken today</span><strong>${data.todayExams}</strong><small>${data.totalExams} submitted exams</small></article><article class="analytics-card"><span>Payments approved</span><strong>${data.todayApproved}</strong><small>${data.activeSubscriptions} active subscriptions</small></article><article class="analytics-card"><span>Revenue today</span><strong>₦${Number(data.todayRevenue).toLocaleString()}</strong><small>₦${Number(data.revenue).toLocaleString()} all time</small></article></div><div class="analytics-columns"><article class="panel analytics-chart"><div class="section-heading"><div><p class="eyebrow">Seven-day pulse</p><h2>Users and exams</h2></div><span class="chart-legend"><b class="legend-users"></b>Users <b class="legend-exams"></b>Exams</span></div><div class="activity-chart">${bars}</div></article><article class="panel analytics-chart"><div class="section-heading"><div><p class="eyebrow">Performance mix</p><h2>Grade distribution</h2></div><strong>${data.averageScore}% avg</strong></div><div class="grade-bars">${grades}</div><div class="analytics-foot"><span>${data.passes} passes</span><span>${data.fails} fails</span></div></article></div>`; } catch (error) { document.querySelector("#analytics-content").innerHTML = `<div class="analytics-empty">${escape(error.message)}</div>`; } }
async function startExam(bankId) { try { exam = await api("exams", { action: "start", bankId }); renderExam(); } catch (error) { notify(error.message, true); } }
function renderExam(remainingSeconds = exam.durationSeconds) { let index = 0; const answers = { ...(exam.answers || {}) }; let saving = false; app.innerHTML = `<section class="exam"><div class="exam-head"><div><p class="eyebrow">Focused practice</p><h1>CBT examination</h1></div><div class="exam-time" id="exam-time">--:--</div></div><div class="exam-layout"><div class="question-panel panel" id="question-panel"></div><aside class="question-map panel"><p class="eyebrow">Progress</p><div id="map"></div><button type="button" class="button danger" id="submit-exam">Submit exam</button></aside></div></section>`; const paint = () => { const question = exam.questions[index]; document.querySelector("#question-panel").innerHTML = `<div class="question-meta"><span>Question ${index + 1} of ${exam.questions.length}</span><span>${Object.keys(answers).length} answered</span></div><h2>${escape(question.prompt)}</h2><div class="choices">${question.choices.map((choice, choiceIndex) => `<button type="button" class="choice ${String(answers[index]) === String(choiceIndex) ? "selected" : ""}" data-choice="${choiceIndex}"><span>${String.fromCharCode(65 + choiceIndex)}</span>${escape(choice)}</button>`).join("")}</div><div class="exam-actions"><button type="button" class="button ghost" id="previous" ${index === 0 ? "disabled" : ""}>Previous</button><button type="button" class="button" id="next">${index === exam.questions.length - 1 ? "Review" : "Next"}</button></div>`; document.querySelectorAll("[data-choice]").forEach(button => button.onclick = async () => { answers[index] = Number(button.dataset.choice); paint(); if (!saving) { saving = true; try { await api("exams", { action: "save", attemptId: exam.attemptId, answers }); } catch (error) { notify("Your answer could not be saved.", true); } finally { saving = false; } } }); document.querySelector("#previous").onclick = () => { index -= 1; paint(); }; document.querySelector("#next").onclick = () => { if (index < exam.questions.length - 1) { index += 1; paint(); } }; document.querySelector("#map").innerHTML = exam.questions.map((_, item) => `<button type="button" class="map-button ${item === index ? "current" : ""} ${answers[item] !== undefined ? "answered" : ""}" data-index="${item}">${item + 1}</button>`).join(""); document.querySelectorAll("[data-index]").forEach(button => button.onclick = () => { index = Number(button.dataset.index); paint(); }); }; paint(); let seconds = Math.max(0, remainingSeconds); const tick = () => { const time = document.querySelector("#exam-time"); if (!time) return; time.textContent = `${String(Math.floor(seconds / 60)).padStart(2, "0")}:${String(seconds % 60).padStart(2, "0")}`; if (seconds <= 0) submitExam(answers); seconds -= 1; }; tick(); examTimer = setInterval(tick, 1000); document.querySelector("#submit-exam").onclick = () => submitExam(answers); async function submitExam(finalAnswers) { clearInterval(examTimer); try { const result = await api("exams", { action: "submit", attemptId: exam.attemptId, answers: finalAnswers }); app.innerHTML = `<section class="result panel"><p class="eyebrow">Exam complete</p><div class="result-score"><h1>${result.percentage}%</h1><strong>Grade ${result.grade}</strong></div><p>You answered ${result.correct} of ${result.total} questions correctly at 2% per question.</p><a class="button" href="#dashboard">Back to dashboard</a></section>`; } catch (error) { notify(error.message, true); } } }
async function historyView() { app.innerHTML = `<section class="narrow"><div class="page-heading"><div><p class="eyebrow">Your progress</p><h1>Exam history.</h1><p class="muted">Review every submitted CBT and see which answers you chose.</p></div></div><div id="exam-history" class="history"><p class="empty">Loading exam history...</p></div></section>`; try { const result = await api("exams", { action: "history" }); const list = document.querySelector("#exam-history"); list.innerHTML = result.attempts.length ? result.attempts.map(item => `<article class="history-row"><div><strong>${item.correct}/${item.total} correct · ${item.percentage}% · Grade ${escape(item.grade || "-")}</strong><span>${item.submittedAt ? new Date(item.submittedAt).toLocaleString() : "Submitted exam"}</span></div><a class="button small ghost" href="#exam/${item.id}">Review</a></article>`).join("") : '<p class="empty">No submitted exams yet.</p>'; } catch (error) { notify(error.message, true); } }
async function reviewView(attemptId) { app.innerHTML = `<section class="narrow"><a href="#history" class="back">← Back to exam history</a><div class="page-heading"><div><p class="eyebrow">Answer review</p><h1>See what you got right.</h1></div><button type="button" class="button small" id="focused-practice">Practice missed questions</button></div><div id="exam-review" class="review-list"><p class="empty">Loading answers...</p></div></section>`; try { const result = await api("exams", { action: "review", attemptId }); const attempt = result.attempt; document.querySelector("#exam-review").innerHTML = `<div class="result-stats"><div><span>Answered</span><strong>${attempt.total - attempt.review.filter(item => item.selectedAnswer === "Not answered").length}</strong></div><div><span>Failed</span><strong>${attempt.incorrect}</strong></div><div><span>Unanswered</span><strong>${attempt.review.filter(item => item.selectedAnswer === "Not answered").length}</strong></div><div><span>Grade</span><strong>${escape(attempt.grade || "-")}</strong></div></div>${attempt.review.map(item => `<article class="review-card ${item.correct ? "is-correct" : "is-incorrect"}"><div class="question-meta"><span>Question ${item.number}</span><strong>${item.correct ? "Correct" : item.selectedAnswer === "Not answered" ? "Unanswered" : "Incorrect"}</strong></div><h2>${escape(item.prompt)}</h2><p><span class="review-label">Your answer</span>${escape(item.selectedAnswer)}</p><p><span class="review-label">Correct answer</span>${escape(item.correctAnswer)}</p>${item.explanation ? `<p class="muted"><span class="review-label">Explanation</span>${escape(item.explanation)}</p>` : ""}<button type="button" class="button small ghost" data-bookmark-question="${item.number}">Bookmark question</button></article>`).join("")}`; document.querySelector("#focused-practice").onclick = async event => { event.currentTarget.disabled = true; try { const focused = await api("exams", { action: "focused-start", attemptId }); exam = focused; renderExam(focused.remainingSeconds); } catch (error) { notify(error.message, true); event.currentTarget.disabled = false; } }; document.querySelectorAll("[data-bookmark-question]").forEach(button => button.onclick = async event => { event.currentTarget.disabled = true; try { await api("exams", { action: "bookmark", attemptId, questionNumber: event.currentTarget.dataset.bookmarkQuestion }); notify("Question bookmarked."); } catch (error) { notify(error.message, true); event.currentTarget.disabled = false; } }); } catch (error) { notify(error.message, true); } }
async function route() { setNav(); if (!firebaseReady) return location.hash === "#faq" ? faqView() : location.hash === "#leaderboard" ? leaderboardView() : location.hash === "#instruction-video" ? instructionVideoView() : location.hash === "#reset-password" ? resetPasswordView() : authView(location.hash === "#register" ? "register" : "login"); if (location.hash === "#faq") return faqView(); if (location.hash === "#leaderboard") return leaderboardView(); if (location.hash === "#instruction-video") return instructionVideoView(); if (location.hash === "#reset-password") return resetPasswordView(); if (!currentUser) return authView(location.hash === "#register" ? "register" : "login"); if (!currentUser.emailVerified) return verificationView(); if (location.hash === "#upload") return uploadView(); if (location.hash === "#practice") return practiceView(); if (location.hash === "#history") return historyView(); if (location.hash.startsWith("#exam/")) return reviewView(location.hash.split("/")[1]); if (location.hash === "#admin") return adminView(); if (location.hash.startsWith("#pay/")) return paymentView(location.hash.split("/")[1]); return dashboard(); }
async function adminVideoPage() { app.innerHTML = `<section class="narrow"><div class="page-heading"><div><p class="eyebrow">Admin content</p><h1>Instruction videos.</h1><p class="muted">Upload the public CBT guide and the separate email verification guide to Cloudinary.</p></div></div><div id="admin-videos-content" class="admin-videos-grid"><p class="empty">Loading video settings...</p></div></section>`; try { const result = await api("videos", null, "GET"); const videos = [{ key: "main", type: "", title: "How to use DANS CBT", value: result.video }, { key: "verify", type: "verify-email", title: "How to verify your email", value: result.verifyVideo }]; document.querySelector("#admin-videos-content").innerHTML = videos.map(item => `<article class="panel admin-video-panel"><p class="eyebrow">${item.key === "verify" ? "Signup guide" : "Main guide"}</p><h2>${item.title}</h2><form class="admin-video-form" data-video-type="${item.type}"><label>Video title<input name="title" maxlength="120" value="${escape(item.value?.title || item.title)}" required></label><label>Choose video<input name="video" type="file" accept="video/mp4,video/webm,.mp4,.webm" required></label><button class="button" type="submit">${item.value ? "Replace video" : "Upload video"}</button><div class="video-upload-status muted"></div></form>${item.value ? `<div class="admin-video-current"><video controls preload="metadata" src="${escape(item.value.videoUrl)}"></video><button class="button danger" data-delete-video="${item.type}" type="button">Remove current video</button></div>` : ""}</article>`).join(""); document.querySelectorAll(".admin-video-form").forEach(form => form.onsubmit = async event => { event.preventDefault(); const file = form.video.files[0]; const button = form.querySelector("button"); const status = form.querySelector(".video-upload-status"); if (!file) return; button.disabled = true; status.textContent = "Preparing upload..."; try { const signature = await api("videos", { action: "upload-signature", videoType: form.dataset.videoType }); const upload = new FormData(); upload.append("file", file); upload.append("api_key", signature.apiKey); upload.append("timestamp", signature.timestamp); upload.append("signature", signature.signature); upload.append("folder", signature.folder); upload.append("public_id", signature.publicId); const uploaded = await fetch(signature.uploadUrl, { method: "POST", body: upload }); const uploadResult = await uploaded.json(); if (!uploaded.ok || !uploadResult.public_id) throw new Error(uploadResult.error?.message || "Video upload failed."); await api("videos", { action: "publish", videoType: form.dataset.videoType, publicId: uploadResult.public_id, title: form.title.value }); notify("Instruction video published."); await adminVideoPage(); } catch (error) { status.textContent = error.message; notify(error.message, true); button.disabled = false; } }); document.querySelectorAll("[data-delete-video]").forEach(button => button.onclick = async () => { button.disabled = true; try { await api("videos", { action: "delete", videoType: button.dataset.deleteVideo }); notify("Instruction video removed."); await adminVideoPage(); } catch (error) { notify(error.message, true); button.disabled = false; } }); } catch (error) { document.querySelector("#admin-videos-content").innerHTML = `<p class="empty">${escape(error.message)}</p>`; } }
const adminRenderer = adminView;
adminView = async () => { await adminRenderer(); };
const dashboardRenderer = renderDashboard;
renderDashboard = (payments, subscriptions) => { dashboardRenderer(payments, subscriptions); const permanent = subscriptions.some(item => item.status === "active" && item.permanent); if (!permanent) return; clearInterval(examTimer); const banner = document.querySelector(".status-banner.active"); const countdown = banner?.querySelector(".countdown"); if (banner && countdown) { banner.querySelector(".status-label").textContent = "SUPER PREMIUM ACTIVATED"; banner.querySelector("h2").textContent = "Super Premium activated."; banner.querySelector("p").textContent = "Use our services forever."; countdown.outerHTML = '<div class="permanent-access">Forever<small>lifetime access</small></div>'; } };
const faqRenderer = faqView;
faqView = () => { faqRenderer(); document.querySelector(".faq-list")?.insertAdjacentHTML("beforeend", '<details><summary>What is Super Premium?</summary><p>Super Premium is a one-time payment of ₦10,000 for one account. Once your payment is approved and activated, that account receives permanent access to DANS CBT services without an expiry date or countdown.</p></details>'); };
const analyticsRenderer = analyticsView;
analyticsView = async () => { await analyticsRenderer(); try { const data = (await api("analytics", null, "GET")).analytics; document.querySelector("#analytics-content")?.insertAdjacentHTML("afterbegin", `<div class="admin-total-analytics"><div class="section-heading"><div><p class="eyebrow">Total analytics</p><h2>All-time platform health</h2></div><span class="muted">Approved payments only</span></div><div class="analytics-grid"><article class="analytics-card analytics-blue"><span>Total users</span><strong>${data.totalUsers}</strong><small>Registered accounts</small></article><article class="analytics-card analytics-green"><span>Users active today</span><strong>${data.todayActiveUsers}</strong><small>Distinct users who completed CBT today</small></article><article class="analytics-card analytics-orange"><span>Total revenue earned</span><strong>₦${Number(data.totalRevenue).toLocaleString("en-NG")}</strong><small>${data.totalApproved} approved payments</small></article></div><div class="admin-daily-analytics"><div class="section-heading"><div><p class="eyebrow">Today</p><h2>Daily analytics</h2></div><span class="muted">Live daily activity</span></div><div class="analytics-grid"><article class="analytics-card"><span>Exams taken today</span><strong>${data.todayExams}</strong><small>Submitted exams</small></article><article class="analytics-card"><span>Approved payments today</span><strong>${data.todayApproved}</strong><small>Reviewed today</small></article><article class="analytics-card"><span>Revenue today</span><strong>₦${Number(data.todayRevenue).toLocaleString("en-NG")}</strong><small>Approved revenue</small></article></div></div></div>`); } catch {} };
const dashboardRenderWithNotices = renderDashboard;
renderDashboard = (payments, subscriptions) => { dashboardRenderWithNotices(payments, subscriptions); const latest = [...payments].sort((left, right) => String(right.createdAt || "").localeCompare(String(left.createdAt || "")))[0]; if (latest?.status === "rejected") document.querySelector("#dashboard-content")?.insertAdjacentHTML("afterbegin", `<div class="status-banner rejected-banner"><div><span class="status-label">SUBSCRIPTION DENIED</span><h2>Your payment was not approved.</h2><p>${escape(latest.rejectionReason || "Please review your payment details and contact support.")} Make another valid subscription to clear this message.</p></div></div>`); };
const dashboardPage = dashboard;
dashboard = async () => { try { userProfile = (await api("profile", { action: "get" })).profile; } catch {} await dashboardPage(); const heading = document.querySelector(".dashboard .page-heading h1"); if (heading && userProfile?.name) heading.textContent = `Ready when you are, ${userProfile.name}.`; };
async function userAnalyticsView() { app.innerHTML = `<section class="analytics-page user-analytics-page"><div class="page-heading"><div><p class="eyebrow">Your performance</p><h1>User analytics.</h1><p class="muted">A colourful view of your exams, passes, fails, and average score.</p></div></div><div id="user-analytics-content" class="analytics-loading"><span class="loader"></span><p>Loading your analytics...</p></div></section>`; try { const result = await api("user-analytics", null, "GET"); const data = result.analytics; const total = Math.max(1, data.passed + data.failed); document.querySelector("#user-analytics-content").innerHTML = `<div class="analytics-grid user-stat-grid"><article class="analytics-card analytics-blue"><span>Exams taken</span><strong>${data.examsTaken}</strong><small>Submitted CBT exams</small></article><article class="analytics-card analytics-green"><span>Passed</span><strong>${data.passed}</strong><small>${Math.round(data.passed / total * 100)}% of attempts</small></article><article class="analytics-card analytics-orange"><span>Failed</span><strong>${data.failed}</strong><small>Keep building your score</small></article><article class="analytics-card analytics-pink"><span>Average score</span><strong>${data.averageScore}%</strong><small>Matches your leaderboard average</small></article></div><div class="user-chart-panel panel"><div><p class="eyebrow">Pass rate</p><h2>Your result mix</h2></div><div class="donut-chart" style="--pass:${data.passed / total * 100}%"><span>${Math.round(data.passed / total * 100)}%<small>passed</small></span></div><div class="chart-legend user-legend"><span><b class="legend-pass"></b>${data.passed} passed</span><span><b class="legend-fail"></b>${data.failed} failed</span></div></div>`; } catch (error) { document.querySelector("#user-analytics-content").innerHTML = `<div class="analytics-empty">${escape(error.message)}</div>`; } }
const originalRoute = route;
route = async () => { if (location.hash === "#profile" && currentUser) return profileView(); if (location.hash === "#bookmarks" && currentUser) return bookmarksView(); if (location.hash === "#user-analytics" && currentUser && !isAdmin) return userAnalyticsView(); if (location.hash === "#admin-videos" && currentUser && isAdmin) return adminVideoPage(); if (location.hash === "#payments" && currentUser && isAdmin) return adminView(); if (location.hash === "#analytics" && currentUser && isAdmin) return analyticsView(); return originalRoute(); };
leaderboardView = async () => { app.innerHTML = `<section class="leaderboard-page"><div class="leaderboard-heading"><div><p class="eyebrow">The DANS CBT hall of excellence</p><h1>Who will take the crown?</h1><p>Ranked by perfect-exam points, exams taken, passes, then fails.</p></div><div class="leaderboard-mark">TOP<br><strong>50</strong></div></div><div id="leaderboard-content" class="leaderboard-loading">Loading rankings...</div></section>`; try { const result = await api("leaderboard", null, "GET"); const entries = result.entries || []; const viewer = result.viewer || { joined: false, rank: null }; const podium = entries.slice(0, 3); const rest = entries.slice(3); const place = index => index === 0 ? "1st" : index === 1 ? "2nd" : "3rd"; const grades = item => Object.entries(item.grades || {}).filter(([, count]) => count).map(([name, count]) => `${name}s: ${count}`).join(", ") || "No grades yet"; const avatar = item => item.profilePicture ? `<img class="leaderboard-avatar" src="${escape(item.profilePicture)}" alt="">` : `<span class="leaderboard-avatar-fallback">${escape((item.displayName || "S").slice(0, 1).toUpperCase())}</span>`; document.querySelector("#leaderboard-content").innerHTML = `${currentUser && viewer.joined ? `<div class="leaderboard-joined"><strong>You're already in the leaderboard.</strong><span>Your current rank is <b>#${viewer.rank || "-"}</b>. Keep practicing to climb higher.</span></div>` : currentUser ? `<div class="leaderboard-join"><div><strong>Ready to be seen?</strong><span>Join with your first name and let your results speak.</span></div><button type="button" class="button" id="join-leaderboard">Join leaderboard</button></div>` : `<div class="leaderboard-join"><div><strong>Want your name on the board?</strong><span>Log in, keep practicing, and compete for the crown.</span></div><a class="button" href="#login">Log in</a></div>`}${entries.length ? `<div class="podium">${podium.map((item, index) => `<article class="podium-card place-${index + 1}">${index === 0 ? '<span class="crown" aria-label="First place">♛</span>' : ""}<span class="podium-place">${place(index)}</span><span class="rank-title">${index === 0 ? "GENIUS" : index === 1 ? "ELITE" : "RISING STAR"}</span>${avatar(item)}<h2>${escape(item.displayName)}</h2><strong>${item.perfectPercentage}%</strong><small>perfect-exam points</small><span class="podium-passes">${item.examsTaken} exams · ${item.passes} passes · ${item.fails} fails</span><span class="podium-grades">${grades(item)}</span></article>`).join("")}</div><div class="leaderboard-table"><div class="leaderboard-row leaderboard-header"><span>Rank</span><span>Student</span><span>Perfect points</span><span>Exams · grades</span></div>${rest.map((item, index) => `<div class="leaderboard-row"><span class="rank-number">${String(index + 4).padStart(2, "0")}</span><span class="leaderboard-student">${avatar(item)}<strong>${escape(item.displayName)}</strong></span><span>${item.perfectPercentage}%</span><span>${item.examsTaken} exams · ${grades(item)}</span></div>`).join("")}</div>` : '<div class="leaderboard-empty"><strong>The board is waiting for its first champion.</strong><span>Complete an exam, then join the leaderboard.</span></div>'}`; document.querySelector("#join-leaderboard")?.addEventListener("click", async event => { event.currentTarget.disabled = true; try { await api("leaderboard", { action: "join" }); notify("You joined the leaderboard."); await leaderboardView(); } catch (error) { notify(error.message, true); event.currentTarget.disabled = false; } }); } catch (error) { document.querySelector("#leaderboard-content").innerHTML = `<div class="leaderboard-empty">${escape(error.message)}</div>`; } };
function verificationView() { app.innerHTML = `<section class="narrow"><div class="page-heading"><div><p class="eyebrow">One more step</p><h1>Verify your email.</h1><p class="muted">We sent a verification link to <strong>${escape(pendingVerificationEmail || currentUser?.email || "your email")}</strong>. Check your Gmail inbox and Spam folder, open the message, and select “Verify email”. Then return here.</p><p class="muted"><strong>Tip:</strong> Gmail may place this message in your Spam folder.</p></div></div><div class="panel auth-form"><button class="button" id="check-verification">I have verified my email</button><button class="button ghost" id="resend-verification">Resend verification email</button><button class="button ghost" id="verification-logout">Use a different account</button></div></section>`; document.querySelector("#check-verification").onclick = async event => { const button = event.currentTarget; button.disabled = true; try { await reload(auth.currentUser); currentUser = auth.currentUser; if (!currentUser.emailVerified) throw new Error("Your email is not verified yet. Open the link in your email, then try again."); await currentUser.getIdToken(true); pendingVerificationEmail = ""; notify("Your account has been verified."); location.hash = "dashboard"; } catch (error) { notify(error.message, true); button.disabled = false; } }; document.querySelector("#resend-verification").onclick = async event => { const button = event.currentTarget; button.disabled = true; try { await sendEmailVerification(auth.currentUser); notify("A new verification email has been sent."); } catch (error) { notify(error.message, true); } finally { button.disabled = false; } }; document.querySelector("#verification-logout").onclick = async () => { pendingVerificationEmail = ""; await signOut(auth); location.hash = "login"; }; }
document.addEventListener("click", event => { if (event.target.closest?.("#verify-email-guide")) verifyEmailGuide(); const link = event.target.closest?.("a[href^='#']"); if (!link || event.defaultPrevented) return; const target = link.getAttribute("href"); if (target && target === location.hash) { event.preventDefault(); route(); } });
authView = function(mode = "login") { const register = mode === "register"; app.innerHTML = `<section class="auth-layout"><div class="auth-copy"><p class="eyebrow">A calmer way to prepare</p><h1>Turn your notes into your next best score.</h1><p>Upload your educational PDFs, build a reliable question bank, and practice with a focused CBT simulator.</p><div class="stat-row"><strong>50</strong><span>randomized questions per exam</span></div></div><form class="panel auth-form" id="auth-form"><div><p class="eyebrow">DANS CBT account</p><h2>${register ? "Create your account" : "Welcome back"}</h2></div>${register ? '<label>Full name or nickname<input name="name" required autocomplete="name"></label><label>Profile picture <span class="muted">optional</span><input name="profilePictureFile" type="file" accept="image/jpeg,image/png,image/webp,.jpg,.jpeg,.png,.webp"></label>' : ""}<label>Email<input name="email" type="email" required autocomplete="email"></label><label>Password<input name="password" type="password" minlength="6" required autocomplete="current-password"></label>${register ? "" : '<p class="form-switch"><a href="#reset-password">Forgot password?</a></p>'}<button class="button" type="submit">${register ? "Create account" : "Log in"}</button><div class="auth-divider"><span>or</span></div><button class="google-button" id="google-sign-in" type="button"><svg aria-hidden="true" viewBox="0 0 24 24"><path fill="#4285F4" d="M21.35 12.23c0-.79-.07-1.55-.22-2.27H12v4.3h5.24a4.48 4.48 0 0 1-1.94 2.94v2.45h3.14c1.84-1.7 2.91-4.2 2.91-7.42Z"/><path fill="#34A853" d="M12 21.5c2.63 0 4.84-.87 6.45-2.35l-3.14-2.45c-.87.58-1.98.93-3.31.93-2.54 0-4.69-1.72-5.46-4.03H3.3v2.53A9.74 9.74 0 0 0 12 21.5Z"/><path fill="#FBBC05" d="M6.54 13.6A5.86 5.86 0 0 1 6.23 12c0-.56.11-1.1.31-1.6V7.87H3.3A9.74 9.74 0 0 0 2.25 12c0 1.57.38 3.05 1.05 4.13l3.24-2.53Z"/><path fill="#EA4335" d="M12 6.38c1.43 0 2.71.49 3.72 1.45l2.79-2.79C16.83 3.34 14.63 2.5 12 2.5a9.74 9.74 0 0 0-8.7 5.37l3.24 2.53c.77-2.31 2.92-4.02 5.46-4.02Z"/></svg><span>Continue with Google</span></button>${register ? '<button class="verify-guide-button" id="verify-email-guide" type="button">Having troubles verifying your account? Click here to watch an instruction guide on how to verify your email.</button>' : ""}<p class="form-switch">${register ? "Already have an account?" : "New to DANS CBT?"} <a href="#${register ? "login" : "register"}">${register ? "Log in" : "Create an account"}</a></p></form></section>`; const form = document.querySelector("#auth-form"); form.addEventListener("submit", async event => { event.preventDefault(); const data = Object.fromEntries(new FormData(form)); const button = form.querySelector("button[type=submit]"); button.disabled = true; button.textContent = "Working..."; try { if (register) { const result = await createUserWithEmailAndPassword(auth, data.email, data.password); await setDoc(doc(db, "users", result.user.uid), { uid: result.user.uid, name: data.name, email: data.email, role: "user", createdAt: serverTimestamp() }); } else await signInWithEmailAndPassword(auth, data.email, data.password); location.hash = "dashboard"; } catch (error) { notify(authErrorMessage(error), true); button.disabled = false; button.textContent = register ? "Create account" : "Log in"; } }); document.querySelector("#google-sign-in").onclick = async event => { const button = event.currentTarget; button.disabled = true; try { const result = await signInWithPopup(auth, new GoogleAuthProvider()); const profile = await getDoc(doc(db, "users", result.user.uid)); if (!profile.exists()) await setDoc(doc(db, "users", result.user.uid), { uid: result.user.uid, name: result.user.displayName || result.user.email?.split("@")[0] || "Google user", email: result.user.email || "", role: "user", createdAt: serverTimestamp() }); location.hash = "dashboard"; } catch (error) { notify(authErrorMessage(error), true); button.disabled = false; } }; };
loadNotifications = async function() { if (!notificationBar || !currentUser?.emailVerified) { if (notificationBar) notificationBar.innerHTML = ""; return; } try { const result = await api("notifications", null, "GET"); const items = result.notifications || []; const unread = items.filter(item => !item.read); notificationBar.innerHTML = `<button class="notification-button" type="button" aria-label="Notifications" title="Notifications"><span class="bell-icon" aria-hidden="true">&#128276;</span>${unread.length ? `<b>${unread.length}</b>` : ""}</button><div class="notification-panel" hidden>${items.length ? `<div class="notification-panel-header"><strong>Notifications</strong><button class="notification-delete-all" type="button" aria-label="Delete all notifications" title="Delete all notifications">&#128465;</button></div>${items.slice(0, 8).map(item => `<article class="notification-item ${item.read ? "" : "unread"}" data-notification-id="${escape(item.id)}"><strong>${escape(item.title)}</strong><span>${escape(item.message)}</span>${item.read ? "" : '<button class="button small ghost notification-read" type="button">Mark as read</button>'}</article>`).join("")}` : '<p class="empty">No notifications yet.</p>'}</div>`; notificationBar.querySelector(".notification-button").onclick = () => { const panel = notificationBar.querySelector(".notification-panel"); panel.hidden = !panel.hidden; }; notificationBar.querySelector(".notification-delete-all")?.addEventListener("click", async event => { event.currentTarget.disabled = true; try { await api("notifications", { action: "delete-all" }); await loadNotifications(); } catch (error) { notify(error.message, true); event.currentTarget.disabled = false; } }); notificationBar.querySelectorAll(".notification-read").forEach(button => button.onclick = async event => { const item = event.currentTarget.closest("[data-notification-id]"); await api("notifications", { action: "mark-read", notificationId: item.dataset.notificationId }); await loadNotifications(); }); } catch { notificationBar.innerHTML = ""; } };
const config = await fetch("/api/config").then(result => result.json()); const firebaseApp = initializeApp(config); auth = getAuth(firebaseApp); db = getFirestore(firebaseApp); firebaseReady = true; onAuthStateChanged(auth, async user => { currentUser = user; isAdmin = false; if (user) { const profile = await getDoc(doc(db, "users", user.uid)); isAdmin = profile.exists() && profile.data().role === "admin"; } route(); }); onAuthStateChanged(auth, user => { if (user && !user.emailVerified) { pendingVerificationEmail = user.email; verificationView(); } }); document.addEventListener("submit", async event => { if (event.target.id !== "auth-form" || !event.target.elements.name) return; event.preventDefault(); event.stopImmediatePropagation(); const data = Object.fromEntries(new FormData(event.target)); const button = event.target.querySelector("button"); button.disabled = true; button.textContent = "Working..."; try { const result = await createUserWithEmailAndPassword(auth, data.email, data.password); await setDoc(doc(db, "users", result.user.uid), { uid: result.user.uid, name: data.name, email: data.email, role: "user", createdAt: serverTimestamp() }); await sendEmailVerification(result.user); pendingVerificationEmail = result.user.email; notify("Verification email sent. Check your Gmail inbox."); verificationView(); } catch (error) { notify(authErrorMessage(error), true); button.disabled = false; button.textContent = "Create account"; } }, true); window.addEventListener("hashchange", route);